            let _ = Box::from_raw(block.as_ptr());
        }
    }

    pub(crate) fn is_closed(&self) -> bool {
        let tail = self.block_tail.load(Acquire);

        unsafe {
            let tail_block = &*tail;
            tail_block.is_closed()
        }
    }
